def get_number():
    """Get a number from user input."""
    while True:
        try:
            num = float(input("Enter a number: "))
            return num
        except ValueError:
            print("That's not a valid number. Please try again.")

def get_operator():
    """Get an operator from user input."""
    operators = {"+": add, "-": subtract, "*": multiply, "/": divide}
    while True:
        operator = input("Enter an operator (+, -, *, /): ").upper()
        if operator in operators:
            return operator, operators[operator]
        else:
            print("That's not a valid operator. Please try again.")

def add(a, b):
    """Perform addition."""
    return a + b

def subtract(a, b):
    """Perform subtraction."""
    return a - b

def multiply(a, b):
    """Perform multiplication."""
    return a * b

def divide(a, b):
    """Perform division."""
    if b == 0:
        raise ValueError("Division by zero is not allowed.")
    return a / b

if __name__ == "__main__":
    num1 = get_number()
    operator, operation = get_operator()
    num2 = get_number()

    try:
        result = operation(num1, num2)
        print(f"{num1} {operator} {num2} = {result}")
    except ValueError as e:
        print(e)
